1	import {
2	  type FirebaseMessagingTypes,
3	  getInitialNotification,
4	  getMessaging,
5	  getToken,
6	  onMessage,
7	  onNotificationOpenedApp,
8	} from "@react-native-firebase/messaging";
9	import { AuthService } from "modules/auth/service/AuthService";
10	import { CallKitService } from "modules/call/service/CallKitService";
11	import { MatrixStorage } from "modules/matrix-client/const/matrix-storage";
12	import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
13	import { NavigationContainerRef } from "modules/navigation/const";
14	import { MatrixNotificationService } from "modules/push-notifications/service/MatrixNotificationService";
15	import { RoomService } from "modules/room/service/RoomService";
16	import { Platform } from "react-native";
17	import {
18	  checkNotifications,
19	  requestNotifications,
20	  RESULTS,
21	} from "react-native-permissions";
22	import {
23	  formatLocalPushNotificationMessage,
24	  getDecryptedEventContent,
25	  isDecryptedEventAnyCallEvent,
26	  isDecryptedEventCall,
27	  isDecryptedEventVerificationStep,
28	} from "../util/formatLocalMessage";
29	import { NotifeeService } from "./NotifeeService";
30	
31	/** Get the current user ID, works in both foreground and background */
32	const getCurrentUserId = (): string | null => {
33	  // Try to get from active instance first (foreground)
34	  const instanceUserId = MatrixCore.instance?.userId();
35	  if (instanceUserId) return instanceUserId;
36	
37	  // Fall back to stored credentials (works in background)
38	  const credentials = MatrixStorage.getLoginCredentials();
39	  return credentials?.userId || null;
40	};
41	
42	/**
43	 * Ensure MatrixService is initialized for background decryption
44	 * Uses lightweight initialization that doesn't start sync service
45	 */
46	const ensureServiceInitialized = async (): Promise<boolean> => {
47	  const notificationClient = MatrixNotificationService.getNotificationClient();
48	  if (notificationClient) return true;
49	
50	  // Foreground: create notification client if possible
51	  if (MatrixCore.instance) {
52	    const client = await MatrixNotificationService.ensureNotificationClient();
53	    return !!client;
54	  }
55	
56	  // Try to restore session with lightweight background method
57	  try {
58	    const restored = await AuthService.restoreSessionForBackground();
59	    return restored;
60	  } catch (error) {
61	    console.error("[Push] Failed to restore session:", error);
62	    return false;
63	  }
64	};
65	
66	const isCurrentlyViewingRoom = (roomId: string): boolean => {
67	  if (!NavigationContainerRef?.isReady()) return false;
68	
69	  try {
70	    const route = NavigationContainerRef?.getCurrentRoute();
71	    return route?.name === "room" && route.params?.roomId === roomId;
72	  } catch {
73	    return false;
74	  }
75	};
76	
77	const handleReceivedMessage = async (
78	  message: FirebaseMessagingTypes.RemoteMessage,
79	) => {
80	  const data = message.data as unknown as NotificationData;
81	  if (!data) return;
82	
83	  // Skip notifications for own messages (works in both foreground and background)
84	  const currentUserId = getCurrentUserId();
85	  if (currentUserId && data.sender === currentUserId) return;
86	
87	  const senderName = data.sender_display_name || data.sender || "Unknown";
88	
89	  // Route unencrypted call events directly to CallKit on iOS (no local notification needed)
90	  const isCallOnIOS =
91	    Platform.OS === "ios" &&
92	    (data.type === "m.call.invite" ||
93	      data.type === "m.call.member" ||
94	      data.type === "m.rtc.notification");
95	
96	  if (isCallOnIOS) {
97	    if (CallKitService.isRingingForRoom(data.room_id)) return;
98	    CallKitService.displayIncomingCall({
99	      roomId: data.room_id,
100	      roomName: data.room_name || senderName,
101	      senderDisplayName: senderName,
102	    });
103	    return;
104	  }
105	
106	  const notificationId = message.messageId || `msg_${Date.now()}`;
107	  const formattedMessage = formatLocalPushNotificationMessage(data);
108	  if (!formattedMessage) return;
109	
110	  // Decrypt encrypted messages, then check if it's a call or a regular message
111	  if (data.type === "m.room.encrypted" && data.room_id && data.event_id) {
112	    try {
113	      const initialized = await ensureServiceInitialized();
114	      if (!initialized) return;
115	
116	      const roomName = RoomService.getRoomInfo(data.room_id)?.displayName();
117	
118	      // Route decrypted call invites to CallKit on iOS
119	      if (Platform.OS === "ios") {
120	        const isCallInvite = await isDecryptedEventCall(
121	          data.room_id,
122	          data.event_id,
123	        );
124	        if (isCallInvite) {
125	          if (CallKitService.isRingingForRoom(data.room_id)) return;
126	          CallKitService.displayIncomingCall({
127	            roomId: data.room_id,
128	            roomName: roomName || data.room_name || senderName,
129	            senderDisplayName: senderName,
130	          });
131	          return;
132	        }
133	      }
134	
135	      // Suppress all other call-related events (Answer, Hangup, Candidates) on all platforms
136	      const isCallEvent = await isDecryptedEventAnyCallEvent(
137	        data.room_id,
138	        data.event_id,
139	      );
140	      if (isCallEvent) return;
141	
142	      // Suppress events the SDK filtered out via push rules (e.g. m.call.hangup on call decline —
143	      // no default Matrix push rule matches it, so the SDK returns EventFilteredOut)
144	      const isFilteredOut =
145	        await MatrixNotificationService.isNotificationFilteredOut(
146	          data.room_id,
147	          data.event_id,
148	        );
149	      if (isFilteredOut) return;
150	
151	      // Suppress protocol-level verification steps (Start, Accept, Key, Mac, Cancel, Done)
152	      const isVerificationStep = await isDecryptedEventVerificationStep(
153	        data.room_id,
154	        data.event_id,
155	      );
156	      if (isVerificationStep) return;
157	
158	      if (isCurrentlyViewingRoom(data.room_id)) return;
159	
160	      const decryptedContent = await getDecryptedEventContent(
161	        data.room_id,
162	        data.event_id,
163	      );
164	
165	      await NotifeeService.create({
166	        title: roomName || formattedMessage.title,
167	        message: decryptedContent
168	          ? `${senderName}: ${decryptedContent}`
169	          : formattedMessage.message,
170	        id: notificationId,
171	        data: { room_id: data.room_id },
172	      });
173	    } catch (error) {
174	      console.error("[Push] Failed to decrypt:", error);
175	    }
176	    return;
177	  }
178	
179	  // Non-encrypted messages — show directly
180	  if (
181	    formattedMessage.room_id &&
182	    isCurrentlyViewingRoom(formattedMessage.room_id)
183	  ) {
184	    return;
185	  }
186	
187	  await NotifeeService.create({
188	    title: formattedMessage.title,
189	    message: formattedMessage.message,
190	    id: notificationId,
191	    data: { room_id: formattedMessage.room_id },
192	  });
193	};
194	
195	const handleNotificationPress = async (
196	  message: FirebaseMessagingTypes.RemoteMessage | null,
197	  isInitialNotification: boolean,
198	) => {
199	  const data = message?.data as unknown as NotificationData;
200	  const roomId = data?.room_id;
201	
202	  if (!roomId || typeof roomId !== "string") return;
203	
204	  // For initial notification (cold start), store the room_id
205	  // and let the Splash screen handle navigation after session restoration
206	  if (isInitialNotification) {
207	    NotifeeService.setPendingRoomId(roomId);
208	    return;
209	  }
210	
211	  // Refresh the room list before navigating to ensure it's up to date
212	  await MatrixCore.refreshRoomList();
213	  await MatrixCore.getClient().awaitRoomRemoteEcho(roomId);
214	
215	  // For background events (app already running), navigate directly to room
216	  NavigationContainerRef.navigate("room", { roomId });
217	};
218	
219	export const PushNotificationsService = {
220	  getToken: async () => await getToken(getMessaging()),
221	  /** Register the device with Matrix homeserver for push notifications
222	   * This should be called after successful login and after push permissions */
223	  registerPusher: async () => {
224	    try {
225	      const fcmToken = await getToken(getMessaging());
226	      await MatrixNotificationService.setPusher(fcmToken);
227	      return true;
228	    } catch (error) {
229	      console.error("Failed to register push notifications:", error);
230	      throw error;
231	    }
232	  },
233	  /** Unregister the device from Matrix homeserver */
234	  unregisterPusher: async () => {
235	    try {
236	      const fcmToken = await getMessaging().getToken();
237	      await MatrixNotificationService.removePusher(fcmToken);
238	      return true;
239	    } catch (error) {
240	      console.error("Failed to unregister push notifications:", error);
241	      throw error;
242	    }
243	  },
244	  registerListeners: async () => {
245	    // Foreground message handler
246	    onMessage(getMessaging(), async (message) => {
247	      await handleReceivedMessage(message);
248	    });
249	
250	    // When the application is opened from a quit state (cold start)
251	    getInitialNotification(getMessaging()).then((remoteMessage) => {
252	      handleNotificationPress(remoteMessage, true);
253	    });
254	
255	    // When the application is running, but in the background
256	    onNotificationOpenedApp(getMessaging(), (remoteMessage) => {
257	      handleNotificationPress(remoteMessage, false);
258	    });
259	  },
260	  /** Handle background messages - called from index.js */
261	  handleBackgroundMessage: async (
262	    remoteMessage: FirebaseMessagingTypes.RemoteMessage,
263	  ) => {
264	    await handleReceivedMessage(remoteMessage);
265	  },
266	  checkPermissions: async () => {
267	    const result = await checkNotifications();
268	    return result.status === RESULTS.GRANTED;
269	  },
270	  requestPermissions: async () => {
271	    const result = await requestNotifications(["alert"]);
272	    return result.status === RESULTS.GRANTED;
273	  },
274	  subscribeToTopic: async (topic: string) => {
275	    await getMessaging().subscribeToTopic(topic);
276	  },
277	  unsubscribeFromTopic: async (topic: string) => {
278	    await getMessaging().unsubscribeFromTopic(topic);
279	  },
280	};
