import { useAtom, useAtomValue } from "jotai";
import { MatrixAtoms } from "modules/matrix-client/jotai";
import { PushNotificationsAtoms } from "modules/push-notifications/jotai";
import { PushNotificationsService } from "modules/push-notifications/service";
import { MatrixNotificationService } from "modules/push-notifications/service/MatrixNotificationService";
import { VoIPPushService } from "modules/push-notifications/service/VoIPPushService";
import { type FC, useEffect } from "react";

export const PushNotificationServiceController: FC = () => {
  const permissions = useAtomValue(PushNotificationsAtoms.isPermitted);
  const client = useAtomValue(MatrixAtoms.matrixClient);
  const [token, setToken] = useAtom(PushNotificationsAtoms.token);

  // Register notification listeners and VoIP push service when permissions are granted
  useEffect(() => {
    if (!permissions) return;
    PushNotificationsService.registerListeners().catch((e) => {
      console.warn("Failed to register notification listeners:", e);
    });
    VoIPPushService.setup();
  }, [permissions]);

  // Fetch FCM token once on mount (token is stable across permission toggles)
  useEffect(() => {
    if (token) return;

    PushNotificationsService.getToken()
      .then(setToken)
      .catch((e) => {
        console.warn("Failed to get FCM token:", e);
      });
  }, [token, setToken]);

  // Register or unregister pusher when permissions/token/client change
  useEffect(() => {
    if (!token || !client) return;

    const handlePusherState = async () => {
      try {
        if (!permissions) {
          await MatrixNotificationService.removePusher(token);
          return;
        }

        const isRegistered = await MatrixNotificationService.isPusherRegistered(token);
        if (!isRegistered) {
          await PushNotificationsService.registerPusher();
        }
      } catch (e) {
        console.warn("Failed to handle pusher state:", e);
      }
    };

    handlePusherState();
  }, [permissions, token, client]);

  return <></>;
};

