import { useIsFocused } from "@react-navigation/native";
import { useAtom, useAtomValue } from "jotai";
import { type FC, useEffect, useMemo } from "react";
import { useAppLifecycle } from "react-native-applifecycle";
import { PushNotificationsAtoms } from "../jotai";
import { PushNotificationsService } from "../service";
import { PushNotificationServiceController } from "./fragments";

export const PushNotificationsProvider: FC = () => {
  const isFocused = useIsFocused();
  const hasAllowedNotificationsIntro = useAtomValue(
    PushNotificationsAtoms.hasAllowedNotificationsIntro,
  );
  const [permissions, setPermissions] = useAtom(
    PushNotificationsAtoms.isPermitted,
  );
  const currentLifecycle = useAppLifecycle();
  const isActive = useMemo(
    () => currentLifecycle === "active",
    [currentLifecycle],
  );

  /**First time when the app is opened, the user is asked for permissions, later when the user changes the permissions in settings, the permissions are checked.*/
  async function getPermissions(type: "request" | "check") {
    const getPermission =
      type === "request"
        ? PushNotificationsService.requestPermissions
        : PushNotificationsService.checkPermissions;

    try {
      const permissions = await getPermission();
      setPermissions(permissions);
    } catch (e) {
      console.warn(e);
    }
  }

  useEffect(() => {
    if (!isFocused || !hasAllowedNotificationsIntro) return;

    getPermissions("request");
  }, [isFocused, hasAllowedNotificationsIntro]);

  useEffect(() => {
    if (!isActive || !isFocused || permissions === null) return;

    getPermissions("check");
  }, [isActive, isFocused, permissions]);

